    int s = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in a = {.sin_family = AF_INET, .sin_port = htons(12345), .sin_addr.s_addr = INADDR_ANY};
    bind(s, (struct sockaddr *)&a, sizeof a);
    listen(s, 1);
    int c = accept(s, NULL, NULL);
    char buf[256];
    while (read(c, buf, sizeof buf) > 0) {
        write(c, buf, strlen(buf));  // echo command back
    }
    close(c);
    close(s);
    return 0;
}
